  "«Кино» — тени, блики, объёмный свет (для ПК). «Ретро» — плёнка и пиксели, легче для телефона. Без озвучки остаются субтитры.": "«Cine»: sombras, reflejos y luz volumétrica (para PC). «Retro»: grano de película y píxeles, más ligero para teléfonos. Sin doblaje, quedan los subtítulos.",
