  "Пока ни одной записи.": "Aún no hay anotaciones.",
  "Фрэнк поднимается на голос. Не отпускай, пока голос не стихнет.": "Frank se levanta y va hacia la voz. No lo sueltes hasta que se apague.",
  "Голос стих. Фрэнк сел на пол и закрыл лицо руками.": "La voz se apagó. Frank se dejó caer al suelo y se tapó la cara con las manos.",
  "Звонит внутренний телефон": "Suena el teléfono interno",
  "В будке. Номер не определён.": "En la caseta. Número desconocido.",
  "Снять трубку": "Descolgar",
  "Не брать": "Dejar que suene",
