  "БУБЛИК": "GALLETA",
  "03.10  Обход. Лампа на 4-м мигает.": "03/10  Ronda. Luz del 4 parpadea.",
  "05.10  Обход. Кошка у баков.": "05/10  Ronda. Gata en la basura.",
  "08.10  Обход. Без происшествий.": "08/10  Ronda. Sin novedad.",
  "10.10  Обход. Без происшествий.": "10/10  Ronda. Sin novedad.",
  "12.10  Лифт ночью ездит сам.": "12/10  El ascensor se mueve solo.",
  "       Техник: «датчик».": "       Técnico: «sensor».",
  "15.10  Гаса зовут с 7-го. По имени.": "15/10  Llaman a Gus desde el 7.",
  "       Голосом Марты.": "       Con la voz de Martha.",
  "       Марта три года как умерла.": "       Martha murió hace 3 años.",
