  "       Такой камеры нет. Не смотри.": "       No existe. No la mires.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ.": "20/10  NO RESPONDAS.",
  "       НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.": "       NO LE ABRAS LA PUERTA.",
  "       САМ К НЕМУ НЕ ХОДИ —": "       NO TE ACERQUES TÚ —",
  "       НИ НА СВЕТ, НИ В ЛИФТ.": "       NI LUZ, NI ASCENSOR.",
