  "       Соль держит. Иду вниз.": "       La sal lo frena. Voy abajo.",
  "28.10  ФРЭНК БЫЛ ЖИВ.": "28/10  FRANK ESTABA VIVO.",
  "       Я НЕ СПУСТИЛСЯ.  — И.": "       NO BAJÉ.  — E.",
  "ЖУРНАЛ НОЧНЫХ СМЕН": "BITÁCORA NOCTURNA",
  "СЕРВЕРНАЯ": "SERVIDORES",
  "Как звали": "¿Nombre",
  "собаку?": "del perro?",
  "НЕ ЗОВИ МЕНЯ.": "NO ME LLAMES.",
  "СТУЧИ ТРИ РАЗА": "GOLPEA 3 VECES",
  "ПАМЯТКА ОХРАННИКУ БЦ «ГОРИЗОНТ»": "INSTRUCCIONES DE VIGILANCIA · CENTRO HORIZON",
  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00 — cerrar la entrada y poner el ascensor en modo nocturno (PARADO).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "Cada hora, revisar las cámaras. Lo anormal, a la bitácora (botón «Anotar»).",
  "Свет на пустых этажах — выключать с пульта.": "Luces en pisos vacíos: apagarlas desde el panel.",
  "Посторонних не впускать.": "No dejar entrar a extraños.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "El teléfono interno sirve para hablar con la seguridad de los edificios vecinos.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(dentro de la tapa trasera, a lápiz) Estática en una cámara: no te quedes mirando. Anota y cambia.",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "12/10  De noche el ascensor se mueve solo. Técnico: «un sensor».",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "15/10  A Gus lo llaman desde el 7. Por su nombre. Con la voz de Martha. Martha murió hace tres años.",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "18/10  CAM 13 en el panel. Esa cámara no existe. No la mires.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20/10  NO RESPONDAS A TU NOMBRE. NO LE ABRAS LA PUERTA. NO TE ACERQUES TÚ — NI A LA LUZ, NI AL ASCENSOR.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21/10  Mamá me llamó. Respondí. La sal lo frena. Voy abajo.",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "El panel pitó: «ENTRADA — ABIERTA».",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "Las cámaras, abajo. Algo raro: «Anotar». Luces, entrada y ascensor: en el panel.",
  "К 22:00 запереть вход и остановить лифт": "Antes de las 22:00, cerrar la entrada y detener el ascensor",
  "Ты как там? Не страшно одному? 😄": "¿Qué tal todo? ¿No te da miedo estar solo? 😄",
  "Нормально. Спи давай.": "Bien. A dormir.",
  "Если честно — жутковато.": "¿Sinceramente? Da un poco de miedo.",
  "Держись! Утром позвоню": "¡Ánimo! Te llamo por la mañana",
  "«Итан?.. Это ты?»": "«¿Ethan…? ¿Eres tú?»",
  "— Да. Это я.": "— Sí. Soy yo.",
  "Молча положить трубку": "Colgar sin decir nada",
  "Рация. Канал уборщика": "Radio. Canal de limpieza",
  "Сквозь шипение — голос Гаса.": "A través del ruido, la voz de Gus.",
  "Не отвечать": "No responder",
  "«Итан… Спустись ко мне»": "«Ethan… Baja a verme»",
  "— Гас! Держись, я сейчас поднимусь!": "— ¡Gus! ¡Aguanta, ya subo!",
  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "Ethan, estoy abajo, en la entrada. Ábreme, por favor, estoy empapada",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Te escondes. Mira las cámaras y anota. Pasos junto a la caseta: «NO RESPIRES».",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "Pasos junto a la caseta. Mantén el botón hasta que se vaya.",
  "Она дышит за стеклом будки. Не отпускай.": "Ella respira tras el vidrio de la caseta. No sueltes.",
  "ЗАТАИТЬСЯ": "NO MOVERSE",
  "НЕ ДЫШУ": "SIN RESPIRAR",
  "Шаги удаляются. Пока.": "Los pasos se alejan. Por ahora.",
  "Я на седьмом. Тут светло и тепло. Поднимись ко мне?": "Estoy en el séptimo. Aquí hay luz y hace calor. ¿Subes a verme?",
  "БУДКА ФРЭНКА": "LA CASETA DE FRANK",
  "ЗВОНОК": "LA LLAMADA",
  "Осмотрись. Нажми на то, что хочешь проверить.": "Echa un vistazo. Toca lo que quieras revisar.",
  "Осмотри будку. Нажми на то, что хочешь проверить.": "Examina la caseta. Toca lo que quieras revisar.",
  "Куртка Фрэнка": "La chaqueta de Frank",
  "Фото под стеклом": "La foto bajo el vidrio",
