  "Сесть за мониторы": "Sentarse frente a los monitores",
  "Марта.\nСедьмой этаж.\nНовый год": "Martha.\nSéptimo piso.\nAño Nuevo",
  "Дневной охранник": "El vigilante de día",
  "Что на самом деле случилось с Фрэнком?": "¿Qué le pasó de verdad a Frank?",
  "Зачем ты стучал в стекло?": "¿Por qué golpeaste el vidrio?",
