  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "Painel: luz dos andares, entrada, elevador. Apague as luzes que sobrarem. Até as 22h, tranque a entrada e pare o elevador.",
