  "CAM 00  БУДКА": "CAM 00  GUARITA",
  "Удачи на первой смене! Не засни там :)": "Boa sorte no primeiro turno! Não vai dormir aí :)",
  "Сменщик протягивает связку. Рука дрожит.": "O vigia do dia estende o molho de chaves. A mão treme.",
  "«Как это — не сдал?»": "“Como assim, não entregou?”",
  "ЖУРНАЛ ФРЭНКА": "DIÁRIO DO FRANK",
  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "NÃO RESPONDA SE CHAMAREM SEU NOME.\nNÃO ABRA A PORTA PRA AQUILO.\nNÃO VÁ ATÉ AQUILO —\nNEM PRA LUZ, NEM PRO ELEVADOR.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "MAMÃE CHAMOU. EU RESPONDI.\nO SAL PROTEGE. VOU DESCER.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Arraste o controle para a esquerda. Ache o momento em que ele ainda está lá.",
  "03:00:00. Гас стоит у двери 707…": "03:00:00. O Gus está parado na porta da 707…",
  "Полиция": "Polícia",
  "На седьмом горит свет. Гаса нет.": "O sétimo está aceso. O Gus sumiu.",
  "Подняться на седьмой": "Subir ao sétimo",
  "Остаться в будке": "Ficar na guarita",
  "Рация зовёт тебя по имени.": "O rádio chama você pelo nome.",
  "Ответить: «Гас, держись!»": "Responder: “Aguenta, Gus!”",
  "Выключить рацию": "Desligar o rádio",
  "Оно оборачивается. Тяни вилку вниз!": "Aquilo está se virando. Puxe o plugue pra baixo!",
  "Не спится :( Как первая смена? Позвони утром": "Sem sono :( Como tá o primeiro turno? Me liga de manhã",
  "минуту назад": "há um minuto",
  "«Итан, открой!»": "“Ethan, abre!”",
  "Открыть": "Abrir",
  "Написать на стекле": "Escrever no vidro",
  "Оно повторяет твоё имя.": "Aquilo repete o seu nome.",
  "Спрятаться в будке": "Se esconder na guarita",
  "Бежать к аварийному выходу": "Correr pra saída de emergência",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "Aquilo caça pelo som. Mantenha o dedo apertado enquanto os passos estiverem perto.",
  "ВНУТРИ": "DENTRO",
  "«Ты со мной», — сказал ты ей. И не соврал.": "“Você tá comigo”, você disse a ela. E não mentiu.",
  "СЕСТРА": "IRMÃ",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "Aquilo foi pra onde ainda ninguém espera. Com a sua voz.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SERVIDORES",
  "CAM −2  ПОДВАЛ": "CAM −2  SUBSOLO",
  "НЕ ЗОВИ МЕНЯ.\nСТУЧИ ТРИ РАЗА.": "NÃO ME CHAME.\nBATA TRÊS VEZES.",
  "Фрэнк жив. Он внизу.": "O Frank está vivo. Lá embaixo.",
  "Спуститься к нему": "Descer até ele",
  "ПОДВАЛ": "SUBSOLO",
  "Темно. Веди фонарём, найди дверь серверной.": "Está escuro. Mova a lanterna e ache a porta da sala de servidores.",
  "Железная дверь. Под ней — свет.": "Uma porta de ferro. Luz por baixo dela.",
  "«Заходи, сынок. Открыто».": "“Pode entrar, filho. Tá aberto.”",
  "Открыть дверь": "Abrir a porta",
  "Постучать три раза": "Bater três vezes",
  "ДЕРЖИ ФРЭНКА": "SEGURE O FRANK",
  "Мать зовёт его из темноты. Не отпускай, пока голос не стихнет.": "A mãe dele chama do escuro. Não solte até a voz se calar.",
  "силы": "força",
  "ДЕРЖАТЬ": "SEGURAR",
  "ДЕРЖУ": "SEGURANDO",
  "Голос стих. Ненадолго.": "A voz se calou. Por enquanto.",
  "CAM 04  ЛЕСТНИЦА": "CAM 04  ESCADA",
  "CAM 02  ХОЛЛ  03:00": "CAM 02  SAGUÃO  03:00",
  "РАССВЕТ": "AMANHECER",
  "Ты ни разу не ответил. Пока.": "Você nunca respondeu. Ainda.",
  "Звонит «Лили».": "“Lily” está ligando.",
  "ТЫ НЕ СПУСТИЛСЯ": "VOCÊ NÃO DESCEU",
  "Ты дожил до утра. Фрэнк — нет.": "Você sobreviveu até de manhã. O Frank, não.",
  "ТЫ ПОСМОТРЕЛ ЕМУ В ЛИЦО": "VOCÊ ENCAROU AQUILO",
  "Не смотри в тринадцатую камеру.": "Não olhe pra câmera treze.",
  "ТЫ ПОШЁЛ НА СВЕТ": "VOCÊ FOI PARA A LUZ",
  "Сам к нему не ходи — ни на свет, ни в лифт.": "Não vá até aquilo — nem pra luz, nem pro elevador.",
  "ТЫ ОТОЗВАЛСЯ": "VOCÊ RESPONDEU",
  "Гас не знал твоего имени. А оно знает.": "O Gus não sabia o seu nome. Aquilo sabe.",
  "ОНО ОБЕРНУЛОСЬ": "AQUILO SE VIROU",
  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "A treze ligou sozinha — puxe o fio, não olhe.",
  "ОНО УСЛЫШАЛО": "AQUILO TE OUVIU",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "Aquilo caça pelo som. Enquanto os passos estiverem perto — não respire.",
  "Остановишься — догонит.": "Se parar, aquilo te pega.",
  "ТЫ ПОШЁЛ НА ЗОВ": "VOCÊ SEGUIU O CHAMADO",
  "Оно умеет звать. Стучать — нет.": "Aquilo sabe chamar. Bater, não.",
  "ФРЭНК УШЁЛ НА ГОЛОС": "FRANK FOI ATRÁS DA VOZ",
  "Держи его, пока голос не стихнет.": "Segure ele até a voz se calar.",
  "Свои до утра подождут.": "Quem é de casa espera até de manhã.",
  "ОБХОД": "RONDA",
  "СЕДЬМОЙ ЭТАЖ": "SÉTIMO ANDAR",
  "ТЫ ОТКРЫЛ ЕЙ": "VOCÊ ABRIU PRA ELA",
  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "A Lily dormia a trezentos quilômetros daqui. Proibida a entrada de estranhos.",
  "ОНО ПРИШЛО": "AQUILO VEIO",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "Três anomalias numa hora passaram despercebidas. Vigie as câmeras, anote o que vir, apague as luzes que sobrarem.",
  "ТЫ ЗАСМОТРЕЛСЯ": "VOCÊ OLHOU DEMAIS",
  "Там, где помехи, кто-то стоит. Не смотри — запиши и переключи.": "Onde tem estática, tem alguém parado. Não olhe: anote e troque.",
  "Внутренний": "Interfone",
  "ТЫ НАЗВАЛСЯ": "VOCÊ DISSE QUEM ERA",
  "Оно знает твоё имя. Ему нужно только, чтобы ты ответил.": "Aquilo sabe o seu nome. Só precisa que você responda.",
  "Новая запись": "Nova anotação",
