  "В трубке": "Na linha",
  "«НЕ СМОТРИ В НЕЁ» — журнал, 18.10": "“NÃO OLHE PRA ELA” — diário, 18/10",
  "среда, 28 октября": "quarta-feira, 28 de outubro",
