  "На этом телефоне «Кино» шло слишком медленно — включена «Ретро». Вернуть: Настройки → Графика.": "„Kino“ lief auf diesem Handy zu langsam, deshalb ist „Retro“ an. Zurück: Einstellungen → Grafik.",
