  "Удачи на первой смене! Не засни там :)": "Viel Glück bei der ersten Schicht! Schlaf nicht ein :)",
  "Сменщик протягивает связку. Рука дрожит.": "Der Kollege hält dir den Schlüsselbund hin. Seine Hand zittert.",
  "«Как это — не сдал?»": "„Was heißt das, keine Übergabe?“",
  "ЖУРНАЛ ФРЭНКА": "FRANKS WACHBUCH",
  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "ANTWORTE NICHT AUF DEINEN NAMEN.\nMACH IHM NICHT AUF.\nGEH NICHT SELBST ZU IHM —\nNICHT INS LICHT, NICHT IN DEN AUFZUG.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "MAMA RIEF. ICH ANTWORTETE.\nDAS SALZ HÄLT. GEHE RUNTER.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Zieh den Regler nach links. Finde, wo er noch da ist.",
  "03:00:00. Гас стоит у двери 707…": "03:00:00. Gus steht vor Tür 707…",
  "Полиция": "Polizei",
  "На седьмом горит свет. Гаса нет.": "Im Siebten brennt Licht. Gus ist weg.",
  "Подняться на седьмой": "Hoch in den Siebten",
  "Остаться в будке": "In der Kabine bleiben",
  "Рация зовёт тебя по имени.": "Das Funkgerät ruft deinen Namen.",
  "Ответить: «Гас, держись!»": "Antworten: „Gus, halt durch!“",
  "Выключить рацию": "Funkgerät ausschalten",
  "Оно оборачивается. Тяни вилку вниз!": "Es dreht sich um. Zieh den Stecker runter!",
  "Не спится :( Как первая смена? Позвони утром": "Kann nicht schlafen :( Wie ist die erste Schicht? Ruf morgen früh an",
  "минуту назад": "vor einer Minute",
  "«Итан, открой!»": "„Ethan, mach auf!“",
  "Открыть": "Aufmachen",
  "Написать на стекле": "Aufs Glas schreiben",
  "Оно повторяет твоё имя.": "Es wiederholt deinen Namen.",
  "Спрятаться в будке": "In der Kabine verstecken",
  "Бежать к аварийному выходу": "Zum Notausgang rennen",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "Es jagt nach Gehör. Halt den Finger drauf, solange die Schritte nah sind.",
  "ВНУТРИ": "DRINNEN",
  "«Ты со мной», — сказал ты ей. И не соврал.": "„Du bist bei mir“, hast du ihr gesagt. Und nicht gelogen.",
  "СЕСТРА": "SCHWESTER",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "Es ging dorthin, wo man es noch nicht erwartet. Mit deiner Stimme.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SERVERRAUM",
  "CAM −2  ПОДВАЛ": "CAM −2  KELLER",
  "НЕ ЗОВИ МЕНЯ.\nСТУЧИ ТРИ РАЗА.": "RUF MICH NICHT.\nKLOPF DREIMAL.",
  "Фрэнк жив. Он внизу.": "Frank lebt. Er ist unten.",
  "Спуститься к нему": "Zu ihm runtergehen",
  "ПОДВАЛ": "KELLER",
  "Темно. Веди фонарём, найди дверь серверной.": "Dunkel. Leuchte mit der Lampe und finde die Tür zum Serverraum.",
  "Железная дверь. Под ней — свет.": "Eine Eisentür. Darunter — Licht.",
  "«Заходи, сынок. Открыто».": "„Komm rein, Junge. Ist auf.“",
  "Открыть дверь": "Tür öffnen",
  "Постучать три раза": "Dreimal klopfen",
  "ДЕРЖИ ФРЭНКА": "HALT FRANK FEST",
  "Мать зовёт его из темноты. Не отпускай, пока голос не стихнет.": "Seine Mutter ruft ihn aus dem Dunkel. Lass nicht los, bis die Stimme verstummt.",
  "силы": "Kraft",
  "ДЕРЖАТЬ": "FESTHALTEN",
  "ДЕРЖУ": "HALTE FEST",
  "Голос стих. Ненадолго.": "Die Stimme ist verstummt. Vorerst.",
  "CAM 04  ЛЕСТНИЦА": "CAM 04  TREPPENHAUS",
  "CAM 02  ХОЛЛ  03:00": "CAM 02  FOYER  03:00",
  "РАССВЕТ": "MORGENGRAUEN",
  "Ты ни разу не ответил. Пока.": "Du hast nie geantwortet. Noch nicht.",
  "Звонит «Лили».": "„Lily“ ruft an.",
  "ТЫ НЕ СПУСТИЛСЯ": "DU BLIEBST OBEN",
  "Ты дожил до утра. Фрэнк — нет.": "Du hast den Morgen erlebt. Frank nicht.",
  "ТЫ ПОСМОТРЕЛ ЕМУ В ЛИЦО": "DU HAST IHM INS GESICHT GESEHEN",
  "Не смотри в тринадцатую камеру.": "Schau nicht auf Kamera dreizehn.",
  "ТЫ ПОШЁЛ НА СВЕТ": "DU BIST INS LICHT GEGANGEN",
  "Сам к нему не ходи — ни на свет, ни в лифт.": "Geh nicht selbst zu ihm — nicht ins Licht, nicht in den Aufzug.",
  "ТЫ ОТОЗВАЛСЯ": "DU HAST DICH GEMELDET",
  "Гас не знал твоего имени. А оно знает.": "Gus kannte deinen Namen nicht. Es schon.",
  "ОНО ОБЕРНУЛОСЬ": "ES HAT SICH UMGEDREHT",
  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "Geht die Dreizehn von selbst an — zieh den Stecker, schau nicht hin.",
  "ОНО УСЛЫШАЛО": "ES HAT DICH GEHÖRT",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "Es jagt nach Gehör. Solange die Schritte nah sind — nicht atmen.",
  "Остановишься — догонит.": "Bleibst du stehen, holt es dich ein.",
  "ТЫ ПОШЁЛ НА ЗОВ": "DU BIST DEM RUF GEFOLGT",
  "Оно умеет звать. Стучать — нет.": "Es kann rufen. Klopfen kann es nicht.",
  "ФРЭНК УШЁЛ НА ГОЛОС": "FRANK IST DER STIMME GEFOLGT",
  "Держи его, пока голос не стихнет.": "Halt ihn fest, bis die Stimme verstummt.",
  "Свои до утра подождут.": "Die Deinen warten bis zum Morgen.",
  "ОБХОД": "RUNDGANG",
  "СЕДЬМОЙ ЭТАЖ": "SIEBTER STOCK",
  "ТЫ ОТКРЫЛ ЕЙ": "DU HAST IHR AUFGEMACHT",
  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "Lily schlief dreihundert Kilometer von hier. Keine Unbefugten einlassen.",
  "ОНО ПРИШЛО": "ES IST GEKOMMEN",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "Drei Anomalien in einer Stunde blieben unbemerkt. Behalte die Kameras im Blick, trag alles ein, mach überflüssiges Licht aus.",
  "ТЫ ЗАСМОТРЕЛСЯ": "DU HAST ZU LANGE HINGESEHEN",
  "Там, где помехи, кто-то стоит. Не смотри — запиши и переключи.": "Wo es rauscht, steht jemand. Schau nicht hin — trag es ein und schalte um.",
  "Внутренний": "Haustelefon",
  "ТЫ НАЗВАЛСЯ": "DU HAST DICH VERRATEN",
  "Оно знает твоё имя. Ему нужно только, чтобы ты ответил.": "Es kennt deinen Namen. Es braucht nur deine Antwort.",
