  "БУБЛИК": "KEKS",
  "03.10  Обход. Лампа на 4-м мигает.": "03.10  Rundgang. Lampe flackert.",
  "05.10  Обход. Кошка у баков.": "05.10  Rundgang. Katze am Müll.",
  "08.10  Обход. Без происшествий.": "08.10  Rundgang. Alles ruhig.",
  "10.10  Обход. Без происшествий.": "10.10  Rundgang. Alles ruhig.",
  "12.10  Лифт ночью ездит сам.": "12.10  Aufzug fährt nachts allein.",
  "       Техник: «датчик».": "       Techniker: „Sensor“.",
  "15.10  Гаса зовут с 7-го. По имени.": "15.10  Jemand ruft Gus aus dem 7.",
  "       Голосом Марты.": "       Beim Namen. Marthas Stimme.",
  "       Марта три года как умерла.": "       Martha ist drei Jahre tot.",
