  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "Ethan, ich bin unten am Eingang. Mach bitte auf, ich bin klatschnass",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Du versteckst dich. Behalte die Kameras im Blick und trag ein. Schritte an der Kabine — „NICHT ATMEN“.",
