  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych est parti et n’est jamais revenu. Toi, tu es revenu. Et celui de l’ascenseur se tient un peu plus près chaque nuit.",
