  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "Les caméras sont les boutons du bas. Passe de l’une à l’autre et retiens ce qui est normal.",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "Un truc qui cloche ? Touche Noter et choisis : lumière, porte, ascenseur, parasites, quelqu’un, son, autre.",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "MIC, en haut à gauche : si les barres sautent, cette caméra capte un son.",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "Pupitre : lumières des étages, entrée, ascenseur. Éteins les lumières inutiles. Avant 22 h, verrouille l’entrée et arrête l’ascenseur.",
  "Три пропущенные странности за час — оно придёт к будке.": "Trois anomalies ratées en une heure, et ça vient à la loge.",
  "Помехи на камере — не засматривайся: записал и переключил.": "Parasites sur une caméra : ne fixe pas. Note et change.",
