  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "Les graphismes « Cinéma » étaient trop sombres sur cet appareil, « Rétro » est donc activé. Pour revenir : Options → Graphismes.",
