  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "Ici s’arrête la partie gratuite : à la porte vitrée, à 3 h 30.",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "Dans le jeu complet, la nuit dure jusqu’à six heures : ce qui arrive si tu ouvres, et si tu n’ouvres pas. Le sous-sol, deux heures de service en plus, quatre fins.",
