  "НОЧЬ 1": "NOTTE 1",
  "БЦ «ГОРИЗОНТ» · 02:55": "CENTRO D'AFFARI HORIZON · 02:55",
  "Нажми, чтобы заступить на смену": "Tocca per iniziare il turno",
  "Сменщик протягивает ключи. Рука дрожит.": "L'altra guardia porge le chiavi. Gli trema la mano.",
  "Взять ключи": "Prendi le chiavi",
  "«А почему втрое?»": "«Perché il triplo?»",
  "Нажми на листок, чтобы прочитать": "Tocca il foglio per leggerlo",
  "1. В 03:00 НА 7 ЭТАЖЕ\nВКЛЮЧИТСЯ СВЕТ.\nНЕ ПОДНИМАЙСЯ": "1. ALLE 3:00 AL PIANO 7\nSI ACCENDONO LE LUCI.\nNON SALIRE",
  "2. ЛИФТ ПРИЕХАЛ САМ —\nНЕ ЗАХОДИ": "2. SE L'ASCENSORE ARRIVA\nDA SOLO — NON ENTRARE",
  "3. ПОСЛЕ ПОЛУНОЧИ\nНИКОГО НЕ ВПУСКАЙ.\nДАЖЕ СВОИХ": "3. DOPO MEZZANOTTE\nNON FAR ENTRARE NESSUNO.\nNEANCHE I TUOI",
  "4. КАМЕРУ 13\nНЕ ВКЛЮЧАЙ": "4. NON ACCENDERE\nLA TELECAMERA 13",
  "«ТРЕТЬЕ ПРАВИЛО — ЛОЖЬ.\nВПУСТИ ЕЁ.»  — М.": "«LA TERZA REGOLA È FALSA.\nFALLA ENTRARE.»  — M.",
  "Внизу что-то приписано ручкой": "In fondo è scarabocchiato qualcosa",
  "ПЕРЕМОТАЙ ЗАПИСЬ": "RIAVVOLGI IL NASTRO",
  "Тяни ползунок влево. Найди момент, когда он ещё жив.": "Trascina il cursore a sinistra: trova quando era ancora vivo.",
  "03:00:00. Он ещё жив…": "03:00:00. È ancora vivo…",
  "Свет на седьмом горит. Уборщик пропал.": "Al settimo c'è luce. L'addetto alle pulizie è sparito.",
  "Подняться и найти его": "Sali a cercarlo",
  "Остаться у мониторов": "Resta ai monitor",
  "Лифт ждёт. Табло: 13.": "L'ascensore aspetta. Display: 13.",
  "Зайти внутрь": "Entra",
  "Считать дальше": "Continua a contare",
  "ВЫДЕРНИ ШНУР": "STACCA IL CAVO",
  "Тяни шнур монитора вниз и держи три секунды.": "Trascina giù il cavo del monitor e tieni premuto tre secondi.",
  "КТО ТАМ?": "CHI È?",
  "Стекло запотело. Протри его пальцем.": "Il vetro è appannato. Pulisci col dito.",
  "Катя": "Katya",
  "Не спится. Ты уже на смене? Я дома, позвони утром.": "Non riesco a dormire. Sei già di turno? Sono a casa, chiamami domattina.",
  "Ключ в замке.": "La chiave è nella serratura.",
  "Повернуть ключ": "Gira la chiave",
  "Отойти от двери": "Allontanati dalla porta",
  "Лифт едет вниз.": "L'ascensore scende.",
  "В будку, под стойку": "In guardiola, sotto il bancone",
  "К аварийному выходу": "All'uscita di emergenza",
  "Ты чего не отвечаешь? Перезвони.": "Perché non rispondi? Richiamami.",
  "НЕ ДЫШИ": "NON RESPIRARE",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "Tieni premuto finché i passi non se ne vanno. Se molli prima, ti sentirà.",
  "СМЕНА ОКОНЧЕНА": "TURNO FINITO",
  "«Ты внутри», — сказал ты ей. И не соврал.": "«Sei dentro», le hai detto. E non hai mentito.",
  "БЕГИ": "CORRI",
  "ТЫ ВЫБРАЛСЯ": "SEI USCITO",
  "Ей правил никто не давал.": "Nessuno le aveva dato le regole.",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "«AIUTO. MENO 2.\nBUSSA TRE VOLTE»",
  "Минус второй. Стучать трижды.": "Meno due. Bussa tre volte.",
  "Спуститься": "Scendi",
  "Остаться на посту": "Resta al tuo posto",
  "ФОНАРИК": "TORCIA",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "Muovi il dito per illuminare. In fondo al corridoio qualcosa fruscia.",
  "Никого. Дверь серверной — там же, в конце.": "Nessuno. La porta della sala server è lì, in fondo.",
  "СЕРВЕРНАЯ −2": "SALA SERVER −2",
  "«Заходи, открыто».": "«Entra, è aperto.»",
  "Толкнуть дверь": "Spingi la porta",
  "Постучать трижды": "Bussa tre volte",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Dietro la porta risuonarono passi bagnati. Poi Katya si mise a piangere.",
  "ДЕРЖИ ДВЕРЬ": "TIENI LA PORTA",
  "Жми чаще. До шести он будет ломиться в дверь.": "Premi più in fretta. Fino alle sei sbatterà contro la porta.",
  "ТЫ ДОЖИЛ ДО УТРА": "HAI SUPERATO LA NOTTE",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych se n'è andato e non è più tornato. Tu sei tornato. E quello all'ascensore ogni notte è un po' più vicino.",
  "Звонит «Катя».": "Chiama «Katya».",
  "Ответить": "Rispondi",
  "Сбросить": "Rifiuta",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. NON CERCARE MIKHALYCH",
  "ПРАВИЛА СОБЛЮДЕНЫ": "REGOLE RISPETTATE",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "Mikhalych è rimasto di sotto. E ora le regole le scrivi tu.",
  "ПРАВИЛО 1 НАРУШЕНО": "REGOLA 1 VIOLATA",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "Alle 3:00 al settimo si accendono le luci. Non salire.",
  "ПРАВИЛО 2 НАРУШЕНО": "REGOLA 2 VIOLATA",
  "Если лифт приехал сам — не заходи.": "Se l'ascensore arriva da solo, non entrare.",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "Ho acceso la tredici. Guardava già nella telecamera. Aspettava.",
  "ПРАВИЛО 4 НАРУШЕНО": "REGOLA 4 VIOLATA",
  "Камеру 13 не включай.": "Non accendere la telecamera 13.",
  "ОНО ТЕБЯ УВИДЕЛО": "QUELLA COSA TI HA VISTO",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "Se la tredici si accende da sola, stacca il cavo.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "TI HA SENTITO",
  "Пока шаги рядом — не дыши.": "Finché i passi sono vicini, non respirare.",
  "ТЕМНОТА ДОГНАЛА": "IL BUIO TI HA RAGGIUNTO",
  "Не оглядывайся. Беги туда, где ещё светло.": "Non voltarti. Corri dove c'è ancora luce.",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "ERA DIETRO LA PORTA",
  "Он умеет звать. Стучать — нет.": "Sa chiamarti per nome. Bussare, no.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "IL CHIAVISTELLO HA CEDUTO",
  "Держи дверь до рассвета. Не сбавляй.": "Tieni la porta fino all'alba. Non rallentare.",
  "ТЫ ОТВЕТИЛ": "HAI RISPOSTO",
  "Ответить — значит впустить.": "Rispondere è farlo entrare.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Vuoto. Pioggia a dirotto. Un'impronta di mano sul vetro?… No, solo gocce.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "Qualcuno all'ascensore?… No. Solo la mia immaginazione.",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "L'addetto alle pulizie finisce il settimo. Almeno qualcuno è vivo, qui dentro.",
