  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "Le telecamere sono i pulsanti in basso. Cambia e ricorda com'è di solito.",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "Noti qualcosa di strano? Tocca Annota e scegli cos'è: luce, porta, ascensore, disturbi, qualcuno, suono, altro.",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "MIC in alto a sinistra: se le barre saltano, su questa telecamera c'è un suono.",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "Console: luci dei piani, ingresso, ascensore. Spegni le luci inutili. Entro le 22:00 chiudi l'ingresso e ferma l'ascensore.",
  "Три пропущенные странности за час — оно придёт к будке.": "Se perdi tre anomalie in un'ora, quella cosa arriva alla guardiola.",
  "Помехи на камере — не засматривайся: записал и переключил.": "Disturbi su una telecamera: non fissarli. Annota e cambia.",
  "Не отзывайся, если зовут по имени. Не открывай дверь.": "Non rispondere se ti chiamano per nome. Non aprire la porta.",
  "В эфире": "Alla radio",
  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "La grafica «Cinema» risultava troppo scura su questo dispositivo, quindi è attiva «Retro». Per tornare: Impostazioni → Grafica.",
  "Поддержать игру": "Sostieni il gioco",
  "Полная версия — {p}": "Gioco completo — {p}",
  "ОТКРОЕШЬ ЕЙ?": "APRIRAI LA PORTA?",
  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "Qui finisce la parte gratuita: alla porta a vetri, alle 3:30.",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "Nel gioco completo la notte dura fino alle sei: cosa succede se apri e se non apri, l'interrato, altre due ore di turno, quattro finali.",
  "Полная версия скачивается на странице игры и работает без интернета.": "Il gioco completo si scarica dalla pagina del gioco e funziona offline.",
  "СПОНСОРЫ ИГРЫ": "SPONSOR DEL GIOCO",
  "Стань первым — твоё имя будет здесь": "Sii il primo: il tuo nome sarà qui",
