  "«Кино» — тени, блики, объёмный свет (для ПК). «Ретро» — плёнка и пиксели, легче для телефона. Без озвучки остаются субтитры.": "«Cinema»: ombre, riflessi, luce volumetrica (per PC). «Retro»: grana di pellicola e pixel, più leggero per i telefoni. Con l'audio parlato disattivato restano i sottotitoli.",
  "Клавиши: F — весь экран, O — повернуть экран, V — озвучка, M — звук.": "Tasti: F — schermo intero, O — ruota lo schermo, V — audio parlato, M — suono.",
