  "ВНУТРИ": "DENTRO",
  "«Ты со мной», — сказал ты ей. И не соврал.": "«Sei con me», le hai detto. E non hai mentito.",
  "СЕСТРА": "SORELLA",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "È andato dove nessuno lo aspetta ancora. Con la tua voce.",
