  "БЦ «ГОРИЗОНТ» · 02:55": "CENTRUM BIZNESOWE HORIZON · 02:55",
  "Нажми, чтобы заступить на смену": "Naciśnij, by zacząć zmianę",
  "Сменщик протягивает ключи. Рука дрожит.": "Dzienny ochroniarz podaje ci klucze. Drży mu ręka.",
  "Взять ключи": "Wziąć klucze",
  "«А почему втрое?»": "„A czemu potrójnie?”",
  "Нажми на листок, чтобы прочитать": "Naciśnij kartkę, by przeczytać",
  "1. В 03:00 НА 7 ЭТАЖЕ\nВКЛЮЧИТСЯ СВЕТ.\nНЕ ПОДНИМАЙСЯ": "1. O 3:00 NA 7. PIĘTRZE\nZAPALI SIĘ ŚWIATŁO.\nNIE IDŹ NA GÓRĘ",
  "2. ЛИФТ ПРИЕХАЛ САМ —\nНЕ ЗАХОДИ": "2. JEŚLI WINDA PRZYJEDZIE\nSAMA — NIE WSIADAJ",
  "3. ПОСЛЕ ПОЛУНОЧИ\nНИКОГО НЕ ВПУСКАЙ.\nДАЖЕ СВОИХ": "3. PO PÓŁNOCY\nNIKOGO NIE WPUSZCZAJ.\nNAWET SWOICH",
  "4. КАМЕРУ 13\nНЕ ВКЛЮЧАЙ": "4. NIE WŁĄCZAJ\nKAMERY 13",
  "«ТРЕТЬЕ ПРАВИЛО — ЛОЖЬ.\nВПУСТИ ЕЁ.»  — М.": "„TRZECIA ZASADA TO KŁAMSTWO.\nWPUŚĆ JĄ.”  — M.",
  "Внизу что-то приписано ручкой": "Na dole coś nabazgrano długopisem",
  "ПЕРЕМОТАЙ ЗАПИСЬ": "PRZEWIŃ NAGRANIE",
  "Тяни ползунок влево. Найди момент, когда он ещё жив.": "Przeciągnij suwak w lewo. Znajdź moment, gdy jeszcze żył.",
  "03:00:00. Он ещё жив…": "03:00:00. Jeszcze żyje…",
  "Свет на седьмом горит. Уборщик пропал.": "Na siódmym piętrze pali się światło. Sprzątacz zniknął.",
  "Подняться и найти его": "Pójść go szukać",
  "Остаться у мониторов": "Zostać przy monitorach",
  "Лифт ждёт. Табло: 13.": "Winda czeka. Wyświetlacz: 13.",
  "Зайти внутрь": "Wsiąść do windy",
  "Считать дальше": "Liczyć dalej",
  "ВЫДЕРНИ ШНУР": "WYRWIJ KABEL",
  "Тяни шнур монитора вниз и держи три секунды.": "Przeciągnij kabel monitora w dół i przytrzymaj przez trzy sekundy.",
  "КТО ТАМ?": "KTO TAM?",
  "Стекло запотело. Протри его пальцем.": "Szyba zaparowała. Przetrzyj ją palcem.",
  "Катя": "Katya",
  "Не спится. Ты уже на смене? Я дома, позвони утром.": "Nie mogę spać. Jesteś już na zmianie? Jestem w domu, zadzwoń rano.",
  "Ключ в замке.": "Klucz tkwi w zamku.",
  "Повернуть ключ": "Przekręcić klucz",
  "Отойти от двери": "Odsunąć się od drzwi",
  "Лифт едет вниз.": "Winda jedzie w dół.",
  "В будку, под стойку": "Do budki, pod ladę",
  "К аварийному выходу": "Do wyjścia awaryjnego",
  "Ты чего не отвечаешь? Перезвони.": "Czemu nie odbierasz? Oddzwoń.",
  "НЕ ДЫШИ": "NIE ODDYCHAJ",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "Trzymaj przycisk, aż kroki się oddalą. Puścisz za wcześnie — to cię usłyszy.",
  "СМЕНА ОКОНЧЕНА": "KONIEC ZMIANY",
  "«Ты внутри», — сказал ты ей. И не соврал.": "„Jesteś w środku” — powiedziałeś jej. I nie skłamałeś.",
  "БЕГИ": "BIEGNIJ",
  "ТЫ ВЫБРАЛСЯ": "WYDOSTAŁEŚ SIĘ",
  "Ей правил никто не давал.": "Nikt nie dał jej tych zasad.",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "„POMÓŻ. MINUS 2.\nPUKAJ TRZY RAZY”",
  "Минус второй. Стучать трижды.": "Minus dwa. Zapukać trzy razy.",
  "Спуститься": "Zejść na dół",
  "Остаться на посту": "Zostać na posterunku",
  "ФОНАРИК": "LATARKA",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "Przesuwaj palcem, żeby świecić. Na końcu korytarza coś szeleści.",
  "Никого. Дверь серверной — там же, в конце.": "Nikogo. Drzwi serwerowni też są tam, na końcu.",
  "СЕРВЕРНАЯ −2": "SERWEROWNIA −2",
  "«Заходи, открыто».": "„Wchodź, otwarte.”",
  "Толкнуть дверь": "Pchnąć drzwi",
  "Постучать трижды": "Zapukać trzy razy",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Za drzwiami zachlupotały mokre kroki. A potem zapłakała Katya.",
  "ДЕРЖИ ДВЕРЬ": "TRZYMAJ DRZWI",
  "Жми чаще. До шести он будет ломиться в дверь.": "Naciskaj szybciej. Do szóstej będzie się dobijać do drzwi.",
  "ТЫ ДОЖИЛ ДО УТРА": "DOŻYŁEŚ DO RANA",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych odszedł i nie wrócił. Ty wróciłeś. A ten przy windzie z każdą nocą stoi trochę bliżej.",
  "Звонит «Катя».": "Dzwoni „Katya”.",
  "Ответить": "Odbierz",
  "Сбросить": "Odrzuć",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. NIE SZUKAJ MIKHALYCHA",
  "ПРАВИЛА СОБЛЮДЕНЫ": "ZASADY PRZESTRZEGANE",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "Mikhalych został na dole. A zasady piszesz teraz ty.",
  "ПРАВИЛО 1 НАРУШЕНО": "ZASADA 1 ZŁAMANA",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "O 3:00 na siódmym piętrze zapali się światło. Nie idź na górę.",
  "ПРАВИЛО 2 НАРУШЕНО": "ZASADA 2 ZŁAMANA",
  "Если лифт приехал сам — не заходи.": "Jeśli winda przyjedzie sama — nie wsiadaj.",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "Włączyłem trzynastkę. Już patrzył w kamerę. Czekał.",
  "ПРАВИЛО 4 НАРУШЕНО": "ZASADA 4 ZŁAMANA",
  "Камеру 13 не включай.": "Nie włączaj kamery 13.",
  "ОНО ТЕБЯ УВИДЕЛО": "TO CIĘ ZOBACZYŁO",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "Jeśli trzynastka włączy się sama — wyrwij kabel.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "TO CIĘ USŁYSZAŁO",
  "Пока шаги рядом — не дыши.": "Dopóki kroki są blisko — nie oddychaj.",
  "ТЕМНОТА ДОГНАЛА": "CIEMNOŚĆ CIĘ DOGONIŁA",
  "Не оглядывайся. Беги туда, где ещё светло.": "Nie oglądaj się. Biegnij tam, gdzie jeszcze jest jasno.",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "TO BYŁO ZA DRZWIAMI",
  "Он умеет звать. Стучать — нет.": "To umie wołać. Pukać — nie.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "ZASUWA NIE WYTRZYMAŁA",
  "Держи дверь до рассвета. Не сбавляй.": "Trzymaj drzwi do świtu. Nie zwalniaj.",
  "ТЫ ОТВЕТИЛ": "ODPOWIEDZIAŁEŚ",
  "Ответить — значит впустить.": "Odpowiedzieć to wpuścić.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Pusto. Ściana deszczu. Na szybie odcisk czyjejś dłoni?… Nie, tylko krople.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "Ktoś przy windzie?… Nie. Przywidziało mi się.",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "Sprzątacz dokańcza siódme piętro. Przynajmniej ktoś w tym budynku żyje.",
  "Рассвет": "Świt",
