  "ГОЛОС": "GŁOS",
  "Нажми камеру 03 — лифты": "Wybierz kamerę 03 — windy",
  "Смотри на табло лифта: «13»": "Spójrz na wyświetlacz windy: „13”",
  "Нажми «Записать» → «Лифт»": "Naciśnij „Zapisz” → „Winda”",
  "MIC слева вверху: столбики прыгают — звук": "MIC u góry po lewej: skaczące słupki to dźwięk",
  "Открой «Пульт»": "Otwórz „Pulpit”",
  "Открой «Журнал»": "Otwórz „Dziennik”",
  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "Kamery to przyciski na dole. Przełączaj je i zapamiętuj, jak jest normalnie.",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "Widzisz coś nie tak? Naciśnij „Zapisz” i wybierz, co to jest: światło, drzwi, winda, zakłócenia, ktoś, dźwięk, inne.",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "MIC u góry po lewej: jeśli słupki skaczą, na tej kamerze jest dźwięk.",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "„Pulpit”: światło na piętrach, wejście, winda. Zbędne światło wyłącz. Do 22:00 zamknij wejście i zatrzymaj windę.",
  "Три пропущенные странности за час — оно придёт к будке.": "Przegap trzy anomalie w ciągu godziny, a to przyjdzie do budki.",
  "Помехи на камере — не засматривайся: записал и переключил.": "Zakłócenia na kamerze: nie wpatruj się. Zapisz i przełącz.",
  "Не отзывайся, если зовут по имени. Не открывай дверь.": "Nie odpowiadaj, gdy wołają cię po imieniu. Nie otwieraj drzwi.",
  "В эфире": "Przez radio",
  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "Grafika „Kino” była na tym urządzeniu zbyt ciemna, więc włączono „Retro”. Aby wrócić: Ustawienia → Grafika.",
  "Поддержать игру": "Wesprzyj grę",
  "Полная версия — {p}": "Pełna wersja — {p}",
  "ОТКРОЕШЬ ЕЙ?": "OTWORZYSZ JEJ?",
  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "Tu kończy się darmowa część: przy szklanych drzwiach, o 3:30.",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "W pełnej wersji noc trwa do szóstej: co się stanie, jeśli otworzysz, a co, jeśli nie. Piwnica, jeszcze dwie godziny zmiany, cztery zakończenia.",
  "Полная версия скачивается на странице игры и работает без интернета.": "Pełną wersję pobierzesz na stronie gry; działa bez internetu.",
  "СПОНСОРЫ ИГРЫ": "SPONSORZY GRY",
  "Стань первым — твоё имя будет здесь": "Bądź pierwszy — tu pojawi się twoje imię",
