  "Удачи на первой смене! Не засни там :)": "Powodzenia na pierwszej zmianie! Tylko nie zaśnij :)",
  "Сменщик протягивает связку. Рука дрожит.": "Dzienny ochroniarz podaje pęk kluczy. Drży mu ręka.",
  "«Как это — не сдал?»": "„Jak to, nie zdał zmiany?”",
  "ЖУРНАЛ ФРЭНКА": "DZIENNIK FRANKA",
  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "NIE ODPOWIADAJ, GDY WOŁAJĄ CIĘ PO IMIENIU.\nNIE OTWIERAJ MU DRZWI.\nSAM DO NIEGO NIE CHODŹ —\nANI DO ŚWIATŁA, ANI DO WINDY.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "MAMA WOŁAŁA. ODEZWAŁEM SIĘ.\nSÓL TRZYMA. SCHODZĘ NA DÓŁ.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Przeciągnij suwak w lewo. Znajdź moment, w którym jeszcze tam jest.",
  "03:00:00. Гас стоит у двери 707…": "03:00:00. Gus stoi przy drzwiach 707…",
  "Полиция": "Policja",
  "На седьмом горит свет. Гаса нет.": "Na siódmym świeci się światło. Gusa nie ma.",
