  "Бежать к аварийному выходу": "Biec do wyjścia awaryjnego",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "To szuka po dźwięku. Trzymaj palec, dopóki kroki są blisko.",
  "ВНУТРИ": "W ŚRODKU",
  "«Ты со мной», — сказал ты ей. И не соврал.": "„Jesteś ze mną” — powiedziałeś jej. I nie skłamałeś.",
  "СЕСТРА": "SIOSTRA",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "Poszło tam, gdzie nikt się go jeszcze nie spodziewa. Twoim głosem.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SERWEROWNIA",
  "CAM −2  ПОДВАЛ": "CAM −2  PIWNICA",
