  "Посторонних не впускать.": "Osób postronnych nie wpuszczać.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "Telefon wewnętrzny — do kontaktu z ochroną sąsiednich budynków.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(na odwrocie okładki, ołówkiem) Zakłócenia na kamerze — nie wpatruj się. Zapisz i przełącz.",
