  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20.10  NIE ODPOWIADAJ, GDY WOŁAJĄ CIĘ PO IMIENIU. NIE OTWIERAJ MU DRZWI. SAM DO NIEGO NIE CHODŹ — ANI DO ŚWIATŁA, ANI DO WINDY.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21.10  Mama wołała. Odezwałem się. Sól trzyma. Schodzę na dół.",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "Pulpit zapiszczał: „WEJŚCIE — OTWARTE”.",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "Kamery są na dole. Coś dziwnego — „Zapisz”. Światło, wejście i winda — na pulpicie.",
  "К 22:00 запереть вход и остановить лифт": "Do 22:00 zamknąć wejście i zatrzymać windę",
  "Ты как там? Не страшно одному? 😄": "Jak tam? Nie boisz się tak sam? 😄",
