  "«Итан?.. Это ты?»": "„Ethan?… To ty?”",
  "— Да. Это я.": "— Tak. To ja.",
  "Молча положить трубку": "Odłożyć słuchawkę bez słowa",
  "Рация. Канал уборщика": "Radio. Kanał sprzątacza",
  "Сквозь шипение — голос Гаса.": "Przez szum — głos Gusa.",
  "Не отвечать": "Nie odpowiadać",
  "«Итан… Спустись ко мне»": "„Ethan… Zejdź do mnie”",
  "— Гас! Держись, я сейчас поднимусь!": "— Gus! Trzymaj się, już idę!",
  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "Ethan, jestem na dole przy wejściu. Otwórz, proszę, przemokłam do suchej nitki",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Ukrywasz się. Patrz na kamery i zapisuj. Kroki przy budce — „NIE ODDYCHAJ”.",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "Kroki tuż przy budce. Trzymaj przycisk, aż odejdzie.",
