  "К аварийному выходу": "Acil çıkışa",
  "Ты чего не отвечаешь? Перезвони.": "Neden cevap vermiyorsun? Geri ara.",
  "НЕ ДЫШИ": "NEFES ALMA",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "Ayak sesleri gidene kadar düğmeyi basılı tut. Erken bırakırsan o şey seni duyar.",
  "СМЕНА ОКОНЧЕНА": "VARDİYA BİTTİ",
  "«Ты внутри», — сказал ты ей. И не соврал.": "“İçeridesin,” dedin ona. Ve yalan söylemedin.",
  "БЕГИ": "KOŞ",
  "ТЫ ВЫБРАЛСЯ": "DIŞARI ÇIKTIN",
  "Ей правил никто не давал.": "Ona kuralları kimse söylememişti.",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "“YARDIM. EKSİ 2.\nKAPIYI ÜÇ KEZ ÇAL”",
  "Минус второй. Стучать трижды.": "Eksi iki. Kapıyı üç kez çal.",
  "Спуститься": "Aşağı in",
  "Остаться на посту": "Görev başında kal",
  "ФОНАРИК": "EL FENERİ",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "Işığı yönlendirmek için parmağını kaydır. Koridorun sonunda bir şey hışırdıyor.",
  "Никого. Дверь серверной — там же, в конце.": "Kimse yok. Sunucu odasının kapısı da orada, en sonda.",
  "СЕРВЕРНАЯ −2": "SUNUCU ODASI −2",
  "«Заходи, открыто».": "“Gir içeri, kapı açık.”",
  "Толкнуть дверь": "Kapıyı it",
  "Постучать трижды": "Kapıyı üç kez çal",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Kapının ardında ıslak ayak sesleri şapırdadı. Sonra Katya ağlamaya başladı.",
  "ДЕРЖИ ДВЕРЬ": "KAPIYI TUT",
  "Жми чаще. До шести он будет ломиться в дверь.": "Daha hızlı dokun. Altıya kadar kapıya çarpıp duracak.",
  "ТЫ ДОЖИЛ ДО УТРА": "GECEYİ ATLATTIN",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych gitti ve bir daha dönmedi. Sen döndün. Asansörün yanındaki ise her gece biraz daha yakında duruyor.",
  "Звонит «Катя».": "“Katya” arıyor.",
  "Ответить": "Cevapla",
  "Сбросить": "Reddet",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. MİKHALYCH'İ ARAMA",
  "ПРАВИЛА СОБЛЮДЕНЫ": "KURALLARA UYULDU",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "Mikhalych aşağıda kaldı. Kuralları artık sen yazıyorsun.",
  "ПРАВИЛО 1 НАРУШЕНО": "KURAL 1 ÇİĞNENDİ",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "03:00'te yedinci katta ışıklar yanar. Yukarı çıkma.",
  "ПРАВИЛО 2 НАРУШЕНО": "KURAL 2 ÇİĞNENDİ",
  "Если лифт приехал сам — не заходи.": "Asansör kendi kendine gelirse binme.",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "On üçü açtım. O, çoktan kameraya bakıyordu. Bekliyordu.",
  "ПРАВИЛО 4 НАРУШЕНО": "KURAL 4 ÇİĞNENDİ",
  "Камеру 13 не включай.": "Kamera 13'ü açma.",
  "ОНО ТЕБЯ УВИДЕЛО": "O SENİ GÖRDÜ",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "On üç kendi kendine açılırsa kabloyu çek.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "O SENİ DUYDU",
  "Пока шаги рядом — не дыши.": "Ayak sesleri yakındayken nefes alma.",
  "ТЕМНОТА ДОГНАЛА": "KARANLIK SENİ YAKALADI",
  "Не оглядывайся. Беги туда, где ещё светло.": "Arkana bakma. Hâlâ ışık olan yere koş.",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "O, KAPININ ARDINDAYDI",
  "Он умеет звать. Стучать — нет.": "O, adınla seslenebilir. Kapıyı çalamaz.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "SÜRGÜ DAYANAMADI",
  "Держи дверь до рассвета. Не сбавляй.": "Kapıyı şafağa kadar tut. Yavaşlama.",
  "ТЫ ОТВЕТИЛ": "CEVAP VERDİN",
  "Ответить — значит впустить.": "Cevap vermek, onu içeri almaktır.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Boş. Sağanak yağmur. Camda bir el izi mi?.. Hayır, sadece yağmur damlaları.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "Asansörün yanında biri mi?.. Hayır. Hayal görmüşüm.",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "Temizlikçi yedinci katı bitiriyor. Hiç değilse bu binada yaşayan biri var.",
