  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "Kameralar alttaki düğmeler. Aralarında geçiş yap ve normalin nasıl olduğunu aklında tut.",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "Ters bir şey mi gördün? Kaydet'e dokun ve ne olduğunu seç: ışık, kapı, asansör, parazit, biri, ses, diğer.",
