  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "ADINA CEVAP VERME.\nONA KAPIYI AÇMA.\nONA KENDİ AYAĞINLA GİTME —\nNE IŞIĞA, NE ASANSÖRE.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "ANNEM SESLENDİ. CEVAP VERDİM.\nTUZ TUTUYOR. AŞAĞI İNİYORUM.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Kaydırıcıyı sola çek. Onun hâlâ orada olduğu anı bul.",
  "03:00:00. Гас стоит у двери 707…": "03:00:00. Gus 707 numaralı kapının yanında duruyor…",
  "Полиция": "Polis",
  "На седьмом горит свет. Гаса нет.": "Yedinci katta ışıklar yanıyor. Gus yok.",
  "Подняться на седьмой": "Yedinci kata çık",
  "Остаться в будке": "Kulübede kal",
  "Рация зовёт тебя по имени.": "Telsiz adınla sesleniyor.",
  "Ответить: «Гас, держись!»": "Cevap ver: “Dayan, Gus!”",
  "Выключить рацию": "Telsizi kapat",
  "Оно оборачивается. Тяни вилку вниз!": "Kameraya dönüyor. Fişi aşağı çek!",
  "Не спится :( Как первая смена? Позвони утром": "Uyuyamıyorum :( İlk vardiya nasıl geçiyor? Sabah ara",
  "минуту назад": "bir dakika önce",
  "«Итан, открой!»": "“Ethan, aç kapıyı!”",
  "Открыть": "Aç",
  "Написать на стекле": "Cama yaz",
  "Оно повторяет твоё имя.": "Adını tekrar edip duruyor.",
  "Спрятаться в будке": "Kulübede saklan",
  "Бежать к аварийному выходу": "Acil çıkışa koş",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "O şey sesle avlanır. Ayak sesleri yakındayken parmağını basılı tut.",
  "ВНУТРИ": "İÇERİDE",
  "«Ты со мной», — сказал ты ей. И не соврал.": "“Benimlesin,” dedin ona. Ve yalan söylemedin.",
  "СЕСТРА": "KIZ KARDEŞ",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "O, henüz kimsenin beklemediği yere gitti. Senin sesinle.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SUNUCU ODASI",
  "CAM −2  ПОДВАЛ": "CAM −2  BODRUM",
  "НЕ ЗОВИ МЕНЯ.\nСТУЧИ ТРИ РАЗА.": "BANA SESLENME.\nKAPIYI ÜÇ KEZ ÇAL.",
  "Фрэнк жив. Он внизу.": "Frank hayatta. Aşağıda.",
  "Спуститься к нему": "Yanına in",
  "ПОДВАЛ": "BODRUM",
  "Темно. Веди фонарём, найди дверь серверной.": "Karanlık. El fenerini gezdirip sunucu odasının kapısını bul.",
  "Железная дверь. Под ней — свет.": "Demir bir kapı. Altında ışık var.",
  "«Заходи, сынок. Открыто».": "“Gir içeri, evlat. Kapı açık.”",
  "Открыть дверь": "Kapıyı aç",
  "Постучать три раза": "Kapıyı üç kez çal",
  "ДЕРЖИ ФРЭНКА": "FRANK'İ TUT",
  "Мать зовёт его из темноты. Не отпускай, пока голос не стихнет.": "Annesi onu karanlıktan çağırıyor. Ses kesilene kadar bırakma.",
  "силы": "güç",
  "ДЕРЖАТЬ": "TUT",
  "ДЕРЖУ": "TUTUYORUM",
  "Голос стих. Ненадолго.": "Ses kesildi. Şimdilik.",
  "CAM 04  ЛЕСТНИЦА": "CAM 04  MERDİVEN",
  "CAM 02  ХОЛЛ  03:00": "CAM 02  LOBİ  03:00",
  "РАССВЕТ": "ŞAFAK",
  "Ты ни разу не ответил. Пока.": "Bir kez bile cevap vermedin. Henüz.",
  "Звонит «Лили».": "“Lily” arıyor.",
  "ТЫ НЕ СПУСТИЛСЯ": "AŞAĞI İNMEDİN",
  "Ты дожил до утра. Фрэнк — нет.": "Sabaha çıktın. Frank çıkamadı.",
  "ТЫ ПОСМОТРЕЛ ЕМУ В ЛИЦО": "ONUN YÜZÜNE BAKTIN",
  "Не смотри в тринадцатую камеру.": "On üç numaralı kameraya bakma.",
  "ТЫ ПОШЁЛ НА СВЕТ": "IŞIĞA GİTTİN",
  "Сам к нему не ходи — ни на свет, ни в лифт.": "Ona kendi ayağınla gitme — ne ışığa, ne asansöre.",
  "ТЫ ОТОЗВАЛСЯ": "ADINA CEVAP VERDİN",
  "Гас не знал твоего имени. А оно знает.": "Gus senin adını bilmiyordu. O biliyor.",
  "ОНО ОБЕРНУЛОСЬ": "O KAMERAYA DÖNDÜ",
  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "On üç kendi kendine açıldı — kabloyu çek, bakma.",
  "ОНО УСЛЫШАЛО": "O SENİ DUYDU",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "O şey sesle avlanır. Ayak sesleri yakındayken nefes alma.",
  "Остановишься — догонит.": "Durursan seni yakalar.",
  "ТЫ ПОШЁЛ НА ЗОВ": "ÇAĞRIYA UYDUN",
  "Оно умеет звать. Стучать — нет.": "O, seslenmeyi bilir. Kapı çalmayı bilmez.",
  "ФРЭНК УШЁЛ НА ГОЛОС": "FRANK SESİN PEŞİNDEN GİTTİ",
  "Держи его, пока голос не стихнет.": "Ses kesilene kadar onu tut.",
  "Свои до утра подождут.": "Yakınların sabaha kadar bekler.",
  "ОБХОД": "DEVRİYE",
  "СЕДЬМОЙ ЭТАЖ": "YEDİNCİ KAT",
  "ТЫ ОТКРЫЛ ЕЙ": "ONA KAPIYI AÇTIN",
  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "Lily iki yüz mil ötede uyuyordu. Yetkisiz ziyaretçi alınmaz.",
  "ОНО ПРИШЛО": "O GELDİ",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "Bir saatte üç tuhaflık gözden kaçtı. Kameraları izle, gördüklerini kaydet, gereksiz ışıkları kapat.",
  "ТЫ ЗАСМОТРЕЛСЯ": "ÇOK UZUN BAKTIN",
  "Там, где помехи, кто-то стоит. Не смотри — запиши и переключи.": "Parazitin olduğu yerde biri duruyor. Bakma — kaydet ve geç.",
  "Внутренний": "Dahili hat",
  "ТЫ НАЗВАЛСЯ": "ADINI SÖYLEDİN",
  "Оно знает твоё имя. Ему нужно только, чтобы ты ответил.": "O, adını biliyor. Tek istediği, senin cevap vermen.",
