  "       Такой камеры нет. Не смотри.": "       Böyle bir kamera yok. Bakma.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ.": "20.10  ADINA CEVAP VERME.",
  "       НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.": "       ONA KAPIYI AÇMA.",
  "       САМ К НЕМУ НЕ ХОДИ —": "       ONA GİTME —",
