  "       Я НЕ СПУСТИЛСЯ.  — И.": "       AŞAĞI İNMEDİM.  — E.",
  "ЖУРНАЛ НОЧНЫХ СМЕН": "GECE VARDİYASI DEFTERİ",
  "СЕРВЕРНАЯ": "SUNUCU ODASI",
  "Как звали": "Köpeğin",
