  "СТУЧИ ТРИ РАЗА": "KAPIYI 3 KEZ ÇAL",
  "ПАМЯТКА ОХРАННИКУ БЦ «ГОРИЗОНТ»": "GÜVENLİK TALİMATI · HORİZON İŞ MERKEZİ",
  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00 — girişi kilitle, asansörü gece moduna al (DURDU).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "Her saat başı — kameraları kontrol et. Ters bir şey varsa deftere kaydet (“Kaydet” düğmesi).",
  "Свет на пустых этажах — выключать с пульта.": "Boş katlardaki ışıkları panelden kapat.",
  "Посторонних не впускать.": "Yetkisiz ziyaretçi alınmaz.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "Dahili telefon, komşu binaların güvenliğiyle iletişim içindir.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(arka kapağın içinde, kurşun kalemle) Kamerada parazit — dik dik bakma. Kaydet ve geç.",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "12.10  Asansör geceleri kendi kendine çalışıyor. Teknisyen: “sensör.”",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "15.10  7. kattan Gus'a sesleniyorlar. Adıyla. Martha'nın sesiyle. Martha üç yıl önce öldü.",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "18.10  Panelde CAM 13. Böyle bir kamera yok. Bakma.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20.10  ADINA CEVAP VERME. ONA KAPIYI AÇMA. ONA KENDİ AYAĞINLA GİTME — NE IŞIĞA, NE ASANSÖRE.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21.10  Annem seslendi. Cevap verdim. Tuz tutuyor. Aşağı iniyorum.",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "Panel bip sesi verdi: “GİRİŞ — AÇIK.”",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "Kameralar altta. Tuhaf bir şey — “Kaydet”. Işıklar, giriş ve asansör — panelde.",
  "К 22:00 запереть вход и остановить лифт": "22:00'ye kadar girişi kilitle ve asansörü durdur",
  "Ты как там? Не страшно одному? 😄": "Nasıl gidiyor? Tek başına korkmuyor musun? 😄",
  "Нормально. Спи давай.": "İyiyim. Hadi uyu.",
  "Если честно — жутковато.": "Açıkçası biraz ürkütücü.",
  "Держись! Утром позвоню": "Dayan! Sabah ararım",
  "«Итан?.. Это ты?»": "“Ethan?.. Sen misin?”",
  "— Да. Это я.": "— Evet. Benim.",
  "Молча положить трубку": "Tek kelime etmeden kapat",
  "Рация. Канал уборщика": "Telsiz. Temizlikçinin kanalı",
  "Сквозь шипение — голос Гаса.": "Cızırtının arasından Gus'un sesi.",
  "Не отвечать": "Cevap verme",
  "«Итан… Спустись ко мне»": "“Ethan… Yanıma in”",
  "— Гас! Держись, я сейчас поднимусь!": "— Gus! Dayan, geliyorum!",
  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "Ethan, aşağıda girişteyim. Lütfen aç, sırılsıklam oldum",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Saklanıyorsun. Kameralara bak ve kaydet. Kulübenin yanında ayak sesleri — “NEFES ALMA”.",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "Ayak sesleri kulübenin hemen yanında. O gidene kadar düğmeyi basılı tut.",
  "Она дышит за стеклом будки. Не отпускай.": "Kulübenin camının ardında soluyor. Bırakma.",
  "ЗАТАИТЬСЯ": "KIPIRDAMA",
  "НЕ ДЫШУ": "NEFES ALMIYORUM",
  "Шаги удаляются. Пока.": "Ayak sesleri uzaklaşıyor. Şimdilik.",
  "Я на седьмом. Тут светло и тепло. Поднимись ко мне?": "Yedinci kattayım. Burası aydınlık ve sıcak. Yanıma çıkar mısın?",
