  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00 — замкнути вхід, ліфт — у нічний режим (СТОП).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "Щогодини — огляд камер. Зауваження — у журнал (кнопка «Записати»).",
