  "Посторонних не впускать.": "Сторонніх не впускати.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "Внутрішній телефон — для зв’язку з охороною сусідніх будівель.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(на звороті обкладинки, олівцем) Перешкоди на камері — не задивляйся. Запиши й перемкни.",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "12.10  Ліфт уночі їздить сам. Технік: «датчик».",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "15.10  Гаса кличуть із 7-го. На ім’я. Голосом Марти. Марта три роки як померла.",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "18.10  На пульті CAM 13. Такої камери немає. Не дивись.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20.10  НЕ ОЗИВАЙСЯ НА ІМ’Я. НЕ ВІДЧИНЯЙ ЙОМУ ДВЕРІ. САМ ДО НЬОГО НЕ ХОДИ — НІ НА СВІТЛО, НІ В ЛІФТ.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21.10  Мама покликала. Я відповів. Сіль тримає. Іду вниз.",
