  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Ти ховаєшся. Стеж за камерами й записуй. Кроки біля будки — «НЕ ДИХАЙ».",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "Кроки біля самої будки. Тримай кнопку, доки вона не піде.",
