  "1. В 03:00 НА 7 ЭТАЖЕ\nВКЛЮЧИТСЯ СВЕТ.\nНЕ ПОДНИМАЙСЯ": "1. 凌晨03:00，7楼的灯\n会亮起。\n不要上去",
  "2. ЛИФТ ПРИЕХАЛ САМ —\nНЕ ЗАХОДИ": "2. 电梯自己来了，\n不要进去",
  "3. ПОСЛЕ ПОЛУНОЧИ\nНИКОГО НЕ ВПУСКАЙ.\nДАЖЕ СВОИХ": "3. 午夜之后\n谁也不要放进来。\n自己人也不行",
  "4. КАМЕРУ 13\nНЕ ВКЛЮЧАЙ": "4. 不要打开\n13号摄像头",
  "«ТРЕТЬЕ ПРАВИЛО — ЛОЖЬ.\nВПУСТИ ЕЁ.»  — М.": "“第三条规则是谎言。\n让她进来。”  — M.",
  "Внизу что-то приписано ручкой": "最下面有一行用笔潦草添上的字",
