  "ВЫДЕРНИ ШНУР": "拔掉电源线",
  "Тяни шнур монитора вниз и держи три секунды.": "把监视器的电源线向下拉，按住三秒。",
  "КТО ТАМ?": "谁在那儿？",
  "Стекло запотело. Протри его пальцем.": "玻璃起雾了。用手指擦一擦。",
  "Катя": "卡佳",
  "Не спится. Ты уже на смене? Я дома, позвони утром.": "睡不着。你已经在上班了吗？我在家，早上给我打电话。",
  "Ключ в замке.": "钥匙插在锁里。",
  "Повернуть ключ": "转动钥匙",
