  "Лифт едет вниз.": "电梯正在下来。",
  "В будку, под стойку": "躲进岗亭，钻到柜台下",
  "К аварийному выходу": "跑向紧急出口",
  "Ты чего не отвечаешь? Перезвони.": "你怎么不接？给我回电话。",
  "НЕ ДЫШИ": "屏住呼吸",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "按住按钮，直到脚步声远去。松手太早，它就会听见你。",
  "СМЕНА ОКОНЧЕНА": "值班结束",
  "«Ты внутри», — сказал ты ей. И не соврал.": "“你在里面。”你对她说。你没有撒谎。",
  "БЕГИ": "快跑",
  "ТЫ ВЫБРАЛСЯ": "你逃出来了",
  "Ей правил никто не давал.": "没有人告诉过她规则。",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "“救我。地下二层。\n敲三下。”",
