  "ФОНАРИК": "手电筒",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "移动手指来照亮。走廊尽头有什么东西在沙沙作响。",
  "Никого. Дверь серверной — там же, в конце.": "没有人。机房的门也在那边，走廊尽头。",
