  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "门后响起湿漉漉的脚步声。然后，卡佳哭了起来。",
  "ДЕРЖИ ДВЕРЬ": "顶住门",
  "Жми чаще. До шести он будет ломиться в дверь.": "再点快一点。到六点之前，它会一直撞门。",
