  "ПРАВИЛА СОБЛЮДЕНЫ": "规则已遵守",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "米哈雷奇留在了下面。现在，规则由你来写。",
  "ПРАВИЛО 1 НАРУШЕНО": "违反规则1",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "03:00，七楼会亮灯。不要上去。",
  "ПРАВИЛО 2 НАРУШЕНО": "违反规则2",
  "Если лифт приехал сам — не заходи.": "电梯自己来了，就不要进去。",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "我打开了十三号。他已经在看着镜头。在等。",
