  "ОНО ТЕБЯ УВИДЕЛО": "它看见你了",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "如果十三号自己亮了，就拔掉电源线。",
  "ОНО УСЛЫШАЛО ТЕБЯ": "它听见了你",
  "Пока шаги рядом — не дыши.": "脚步声在附近时，别呼吸。",
