  "ТЫ ОТВЕТИЛ": "你答应了",
  "Ответить — значит впустить.": "答应，就等于放它进来。",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "空无一人。大雨如注。玻璃上有个手掌印？……不，只是水珠。",
  "У лифта кто-то стоит?.. Нет. Показалось.": "电梯旁站着人？……没有。是我看错了。",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "清洁工快拖完七楼了。至少这栋楼里还有个活人。",
