  "Нажми камеру 03 — лифты": "点击03号摄像头——电梯",
  "Смотри на табло лифта: «13»": "看电梯显示屏：“13”",
  "Нажми «Записать» → «Лифт»": "点击“记录”→“电梯”",
  "MIC слева вверху: столбики прыгают — звук": "左上角 MIC：条形跳动，就是有声音",
  "Открой «Пульт»": "打开“控制台”",
  "Открой «Журнал»": "打开“日志”",
  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "摄像头就是下方的按钮。多切换几个，记住它们平时的样子。",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "发现不对劲，就点“记录”，选出是什么：灯光、门、电梯、雪花、有人、声音、其他。",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "左上角 MIC：条形跳动，说明这个摄像头里有声音。",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "“控制台”：各层灯光、入口、电梯。多余的灯要关掉。22:00 前锁好入口，让电梯停运。",
  "Три пропущенные странности за час — оно придёт к будке.": "一小时内漏掉三个异常，它就会来到岗亭。",
  "Помехи на камере — не засматривайся: записал и переключил.": "摄像头出现雪花——别盯着看：记录下来，然后切换。",
  "Не отзывайся, если зовут по имени. Не открывай дверь.": "有人叫你名字，别答应。别开门。",
  "В эфире": "对讲机里",
  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "此设备上“电影”画质显示过暗，已切换为“复古”。要改回来：设置 → 画质。",
  "Поддержать игру": "支持游戏",
  "Полная версия — {p}": "完整版 — {p}",
  "ОТКРОЕШЬ ЕЙ?": "你会给她开门吗？",
  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "免费部分到此为止——就停在玻璃门前，03:30。",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "完整版里，这一夜会一直持续到六点：开门会怎样，不开又会怎样；还有地下室、再多两个小时的值班，以及四个结局。",
  "Полная версия скачивается на странице игры и работает без интернета.": "完整版可在游戏页面下载，无需联网即可游玩。",
