  "Удачи на первой смене! Не засни там :)": "第一次值班，加油！别睡着了哦 :)",
  "Сменщик протягивает связку. Рука дрожит.": "白班保安递来钥匙串。他的手在发抖。",
  "«Как это — не сдал?»": "“没来交班，是什么意思？”",
  "ЖУРНАЛ ФРЭНКА": "弗兰克的日志",
  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "有人叫你名字，别答应。\n别给它开门。\n别自己去找它——\n别走向亮光，别进电梯。",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "妈妈叫我了。我答应了。\n盐挡得住它。我下去了。",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "向左拖动滑块。找到他还在的那一刻。",
  "03:00:00. Гас стоит у двери 707…": "03:00:00。格斯站在707室门口……",
