  "ТЫ ПОШЁЛ НА СВЕТ": "你走向了亮光",
  "Сам к нему не ходи — ни на свет, ни в лифт.": "别自己去找它——别走向亮光，别进电梯。",
  "ТЫ ОТОЗВАЛСЯ": "你回应了",
  "Гас не знал твоего имени. А оно знает.": "格斯不知道你的名字。它却知道。",
  "ОНО ОБЕРНУЛОСЬ": "它转过身了",
  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "十三号自己亮了——拔掉电源线，别看。",
  "ОНО УСЛЫШАЛО": "它听见了",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "它循着声音找人。脚步声在附近时——别呼吸。",
  "Остановишься — догонит.": "一停下，它就会追上你。",
  "ТЫ ПОШЁЛ НА ЗОВ": "你循着呼唤去了",
  "Оно умеет звать. Стучать — нет.": "它会叫人。不会敲门。",
  "ФРЭНК УШЁЛ НА ГОЛОС": "弗兰克朝声音走去",
  "Держи его, пока голос не стихнет.": "拉住他，直到那声音停下。",
  "Свои до утра подождут.": "自己人，等到天亮也不迟。",
  "ОБХОД": "巡查",
  "СЕДЬМОЙ ЭТАЖ": "七楼",
  "ТЫ ОТКРЫЛ ЕЙ": "你给她开了门",
  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "莉莉睡在三百公里之外。无关人员不得入内。",
  "ОНО ПРИШЛО": "它来了",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "一小时内有三个异常无人理会。盯住摄像头，及时记录，把多余的灯关掉。",
  "ТЫ ЗАСМОТРЕЛСЯ": "你盯得太久了",
  "Там, где помехи, кто-то стоит. Не смотри — запиши и переключи.": "有雪花的地方，站着什么人。别盯着看——记录下来，然后切换。",
