  "Фрэнк поднимается на голос. Не отпускай, пока голос не стихнет.": "弗兰克正站起来，朝那声音走去。声音没停之前，别松手。",
  "Голос стих. Фрэнк сел на пол и закрыл лицо руками.": "声音停了。弗兰克坐在地上，双手捂住了脸。",
