  "       Голосом Марты.": "       用的是玛莎的声音。",
  "       Марта три года как умерла.": "       玛莎已经去世三年了。",
  "18.10  На пульте CAM 13.": "10/18  控制台上出现CAM 13。",
  "       Такой камеры нет. Не смотри.": "       没有这个摄像头。别看。",
