  "       НИ НА СВЕТ, НИ В ЛИФТ.": "       别走向亮光，别进电梯。",
  "21.10  Мама позвала. Я ответил.": "10/21  妈妈叫我了。我答应了。",
  "       Соль держит. Иду вниз.": "       盐挡得住它。我下去了。",
  "28.10  ФРЭНК БЫЛ ЖИВ.": "10/28  弗兰克还活着。",
  "       Я НЕ СПУСТИЛСЯ.  — И.": "       我没有下去。  — 伊森",
