  "собаку?": "叫什么？",
  "НЕ ЗОВИ МЕНЯ.": "别喊我。",
  "СТУЧИ ТРИ РАЗА": "敲三下",
  "ПАМЯТКА ОХРАННИКУ БЦ «ГОРИЗОНТ»": "地平线商务中心保安须知",
  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00——锁好入口，电梯切换为夜间模式（停运）。",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "每小时检查一遍摄像头。发现问题记入日志（“记录”按钮）。",
  "Свет на пустых этажах — выключать с пульта.": "空楼层的灯要在控制台关掉。",
  "Посторонних не впускать.": "无关人员不得入内。",
  "Внутренний телефон — для связи с охраной соседних зданий.": "内线电话用于联系相邻大楼的保安。",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "（封底内侧，铅笔所写）摄像头出现雪花——别盯着看。记录下来，然后切换。",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "10/12  夜里电梯自己会动。技术员说是传感器。",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "10/15  7楼有人叫格斯。叫的是他的名字。用的是玛莎的声音。玛莎已经去世三年了。",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "10/18  控制台上出现了CAM 13。没有这个摄像头。别看。",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "10/20  有人叫你名字，别答应。别给它开门。别自己去找它——别走向亮光，别进电梯。",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "10/21  妈妈叫我了。我答应了。盐挡得住它。我下去了。",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "控制台嘀了一声：“入口——开启”。",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "摄像头在下方。发现异常就点“记录”。灯光、入口和电梯在“控制台”。",
  "К 22:00 запереть вход и остановить лифт": "22:00 前锁好入口并让电梯停运",
  "Ты как там? Не страшно одному? 😄": "你怎么样？一个人不害怕吗？😄",
  "Нормально. Спи давай.": "还行。快睡吧。",
  "Если честно — жутковато.": "说实话，有点渗人。",
  "Держись! Утром позвоню": "撑住！早上我打给你",
  "«Итан?.. Это ты?»": "“伊森？……是你吗？”",
  "— Да. Это я.": "— 对。是我。",
  "Молча положить трубку": "一言不发地挂断",
  "Рация. Канал уборщика": "对讲机。清洁工频道",
  "Сквозь шипение — голос Гаса.": "嘶嘶的杂音里，传来格斯的声音。",
  "Не отвечать": "不回应",
  "«Итан… Спустись ко мне»": "“伊森……下来找我”",
  "— Гас! Держись, я сейчас поднимусь!": "— 格斯！撑住，我这就上去！",
  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "伊森，我在楼下入口。求你开门，我浑身都湿透了",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "你正躲着。盯住摄像头，及时记录。脚步声靠近岗亭时——“屏住呼吸”。",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "脚步声就在岗亭外。按住按钮，直到她走开。",
  "Она дышит за стеклом будки. Не отпускай.": "她就在岗亭玻璃外呼吸。别松手。",
