  "Тяни шнур монитора вниз и держи три секунды.": "モニターのコードを下へ引き、3秒間そのままにしろ。",
  "КТО ТАМ?": "誰だ？",
  "Стекло запотело. Протри его пальцем.": "ガラスが曇っている。指でぬぐえ。",
  "Катя": "カーチャ",
  "Не спится. Ты уже на смене? Я дома, позвони утром.": "眠れない。 もう勤務中？ 家にいるよ。 朝に電話して。",
  "Ключ в замке.": "鍵は鍵穴に刺さっている。",
  "Повернуть ключ": "鍵を回す",
  "Отойти от двери": "ドアから離れる",
  "Лифт едет вниз.": "エレベーターが降りてくる。",
  "В будку, под стойку": "守衛室のカウンターの下へ",
  "К аварийному выходу": "非常口へ",
  "Ты чего не отвечаешь? Перезвони.": "なんで出ないの？ かけ直して。",
  "НЕ ДЫШИ": "息をするな",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "足音が去るまで、ボタンを押し続けろ。早く離すと、それに聞かれる。",
  "СМЕНА ОКОНЧЕНА": "勤務終了",
  "«Ты внутри», — сказал ты ей. И не соврал.": "「もう中にいるよ」と、彼女に言った。嘘ではなかった。",
  "БЕГИ": "走れ",
  "ТЫ ВЫБРАЛСЯ": "脱出した",
  "Ей правил никто не давал.": "彼女にルールを教えた者は、誰もいなかった。",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "「助けて。地下2階。\nノックは三回」",
  "Минус второй. Стучать трижды.": "地下2階。ノックは三回。",
  "Спуститься": "降りる",
  "Остаться на посту": "持ち場に残る",
  "ФОНАРИК": "懐中電灯",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "指を動かして照らせ。廊下の突き当たりで、何かがかさかさと音を立てている。",
  "Никого. Дверь серверной — там же, в конце.": "誰もいない。サーバー室の扉も、あの突き当たりにある。",
  "СЕРВЕРНАЯ −2": "サーバー室 −2",
  "«Заходи, открыто».": "「入っておいで、開いてるよ。」",
  "Толкнуть дверь": "ドアを押す",
  "Постучать трижды": "三回ノックする",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "ドアの向こうで、濡れた足音がぴちゃぴちゃと鳴った。やがて、カーチャが泣き出した。",
  "ДЕРЖИ ДВЕРЬ": "ドアを押さえろ",
  "Жми чаще. До шести он будет ломиться в дверь.": "もっと速く連打。6時まで、それはドアを叩きつけ続ける。",
  "ТЫ ДОЖИЛ ДО УТРА": "夜を生き延びた",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "ミハリチは出ていって、戻らなかった。あなたは戻ってきた。そして、エレベーターのそばに立つそれは、夜ごとに少しずつ近くなっている。",
  "Звонит «Катя».": "「カーチャ」から着信。",
  "Ответить": "出る",
  "Сбросить": "切る",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. ミハリチを探すな",
  "ПРАВИЛА СОБЛЮДЕНЫ": "ルールを守った",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "ミハリチは下に残った。そして今度は、あなたがルールを書く番だ。",
  "ПРАВИЛО 1 НАРУШЕНО": "ルール1違反",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "3:00に7階の明かりがつく。上がるな。",
  "ПРАВИЛО 2 НАРУШЕНО": "ルール2違反",
  "Если лифт приехал сам — не заходи.": "エレベーターが勝手に来ても、乗るな。",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "13番をつけた。それはもうカメラを見ていた。待っていた。",
  "ПРАВИЛО 4 НАРУШЕНО": "ルール4違反",
  "Камеру 13 не включай.": "13番カメラをつけるな。",
  "ОНО ТЕБЯ УВИДЕЛО": "それに見られた",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "13番が勝手についたら、コードを抜け。",
  "ОНО УСЛЫШАЛО ТЕБЯ": "それに聞かれた",
  "Пока шаги рядом — не дыши.": "足音が近いあいだは、息をするな。",
  "ТЕМНОТА ДОГНАЛА": "闇に追いつかれた",
  "Не оглядывайся. Беги туда, где ещё светло.": "振り返るな。まだ明るいほうへ走れ。",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "ドアの向こうにそれがいた",
  "Он умеет звать. Стучать — нет.": "それは名前を呼べる。ノックはできない。",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "かんぬきがもたなかった",
  "Держи дверь до рассвета. Не сбавляй.": "夜明けまでドアを押さえろ。ペースを落とすな。",
  "ТЫ ОТВЕТИЛ": "返事をした",
  "Ответить — значит впустить.": "返事をすることは、それを招き入れること。",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "誰もいない。壁のような雨。ガラスに手形？……いや、ただの雨粒。",
  "У лифта кто-то стоит?.. Нет. Показалось.": "エレベーターのそばに誰か……？ いや、気のせい。",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "清掃員が7階の仕上げをしている。この建物にも、生きている人間が少なくとも一人はいる。",
  "Рассвет": "夜明け",
  "Пятое правило": "第五のルール",
