  "18+ · жестокость и кровь · лучше в наушниках · в игре есть вспышки света и резкие звуки": "18+ · 暴力・流血表現 · ヘッドホン推奨 · 光の点滅と大きな音を含む",
  "Жестокость, кровь и сцены насилия": "暴力、流血、残酷な描写",
  "Лучше в наушниках · в игре есть вспышки света": "ヘッドホン推奨 · 光の点滅を含む",
