  "ПУЛЬТ «ЩИТ» · ДИСПЕТЧЕР ВЕРА": "シールド指令センター · ヴェラ",
  "Пропустить обучение": "チュートリアルをスキップ",
  "Как играть": "遊び方",
  "Пройти обучение снова": "チュートリアルをもう一度",
  "Смена началась. Удачи.": "勤務開始。幸運を。",
  "пульт «Щит»": "シールド指令センター",
  "ВЕРА": "ヴェラ",
  "ГОЛОС": "声",
  "Нажми камеру 03 — лифты": "CAM 03（エレベーター）をタップ",
  "Смотри на табло лифта: «13»": "エレベーターの表示を見る：「13」",
  "Нажми «Записать» → «Лифт»": "「記録」→「エレベーター」をタップ",
  "MIC слева вверху: столбики прыгают — звук": "左上のMIC：バーが跳ねたら、音がしている",
  "Открой «Пульт»": "「操作盤」を開く",
  "Открой «Журнал»": "「日誌」を開く",
  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "カメラは下のボタン。切り替えながら、ふだんの状態を覚えておく。",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "おかしなものを見つけたら「記録」をタップし、種類を選ぶ：照明、ドア、エレベーター、ノイズ、誰か、音、その他。",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "左上のMIC：バーが跳ねたら、そのカメラで音がしている。",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "「操作盤」：各階の照明、入口、エレベーター。余計な照明は消す。22:00までに入口を施錠し、エレベーターを止める。",
  "Три пропущенные странности за час — оно придёт к будке.": "1時間に異常を3つ見逃すと、それが守衛室に来る。",
  "Помехи на камере — не засматривайся: записал и переключил.": "カメラにノイズ：見つめない。記録して、切り替える。",
  "Не отзывайся, если зовут по имени. Не открывай дверь.": "名前を呼ばれても返事をするな。ドアを開けるな。",
  "В эфире": "無線通信中",
  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "この端末では「シネマ」の画面が暗すぎたため、「レトロ」に切り替えました。元に戻すには：設定 → グラフィック。",
  "Поддержать игру": "ゲームを応援",
  "Полная версия — {p}": "製品版 — {p}",
  "ОТКРОЕШЬ ЕЙ?": "ドアを開けるか？",
  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "ここで無料パートは終わりです。ガラスのドアの前、3:30。",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "製品版では、夜は6時まで続きます。ドアを開けたら、あるいは開けなかったら、何が起きるのか。地下、さらに2時間の勤務、そして四つのエンディング。",
  "Полная версия скачивается на странице игры и работает без интернета.": "製品版はゲームのページからダウンロードでき、オフラインで遊べます。",
  "СПОНСОРЫ ИГРЫ": "スポンサー",
  "Стань первым — твоё имя будет здесь": "最初のひとりに — あなたの名前がここに載ります",
  "Сыграть ещё раз": "もう一度遊ぶ",
  "Попробовать снова": "やり直す",
