  "На этом телефоне «Кино» шло слишком медленно — включена «Ретро». Вернуть: Настройки → Графика.": "このスマホでは「シネマ」の動作が重すぎたため、「レトロ」に切り替えました。元に戻すには：設定 → グラフィック。",
  "До шести ещё полтора часа. Осмотрись.": "6時まで、あと1時間半。あたりを見回せ。",
