  "«Кино» — тени, блики, объёмный свет (для ПК). «Ретро» — плёнка и пиксели, легче для телефона. Без озвучки остаются субтитры.": "「シネマ」：影、反射、ボリュームライト（PC向け）。「レトロ」：フィルムの質感とピクセル、スマホ向けで軽い。音声をオフにしても字幕は残る。",
