  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "무료 체험은 여기까지예요 — 03:30, 유리문 앞.",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "정식 버전에서는 밤이 6시까지 이어져요. 문을 열면 어떻게 되는지, 열지 않으면 어떻게 되는지. 지하, 두 시간 더 이어지는 근무, 네 가지 엔딩.",
  "Полная версия скачивается на странице игры и работает без интернета.": "정식 버전은 게임 페이지에서 내려받을 수 있고, 오프라인으로 즐길 수 있어요.",
